      const taken = Object.values(sh.lineup).filter(Boolean), role = n => SHEET.player(sh, n).roleCode;
      const res = r => Object.keys(sh.stats.attacks || {}).filter(n => role(n) === r && !taken.includes(n) && att(n) > 0).sort((x, y) => att(y) - att(x));
