    const ruleTxt = (ru) => `${muName(sh, ru.x, true)} ${ru.t === 'blk' ? 'a muro su' : ru.t === 'noblk' ? 'NON a muro su' : ru.t === 'rec' ? `riceve in ${ru.z} sulla battuta di` : `NON riceve in ${ru.z} sulla battuta di`} ${muName(sh, ru.y)}`;
