      const rv = muRecv(mu.ours, pr.r, mu.ourL), line = ['Z5', 'Z6', 'Z1'].map(z => { const n = Object.keys(rv).find(k => rv[k] === z); const e = D.ourRec(n); return `${z} ${nmO(n)}${e != null ? ` (${e}%)` : ''}`; }).join(' · ');
      const so = D.theirSo(s), sv = muPos(mu.ours, ps.r)[0], tsv = muPos(mu.theirs, pr.s)[0], v1 = D.ourSrv(sv), v2 = D.theirSrv(tsv);
