  // plan for the bench scout (scout-panchina): for each of their rotations, where to serve and what to block
  function muPlan(sh) {
    const R = muRank(sh); if (!R) return null;
    const { mu, D, L } = R, x = L.find(y => y.c === mu.pick) || L[0], T = sh.stats.ts || {};
    const nmT = n => muName(sh, n);
    const roleT = n => { const i = mu.theirs.indexOf(n); return i >= 0 ? MU_ROLE[i] : n === mu.theirL ? 'L' : ''; };
    const rot = {};
    for (const s of SHEET.ROTS) {
      const rv = muRecv(mu.theirs, s, mu.theirL), cand = [];
      for (const [n, z] of Object.entries(rv)) for (const ty of ['float', 'spin']) {
        const o = T.recP?.[n]?.[`${ty}|${z}`], t = T.recP?.[n]?.[`${ty}|tot`];
        const use = o?.n >= 5 ? o : t?.n >= 8 ? t : null; if (!use) continue;
        cand.push({ n, name: nmT(n), zone: z, type: ty, eff: effR(use), cnt: use.n, cell: use === o });
      }
      cand.sort((a, b) => a.eff - b.eff);
      const seen = new Set(), serve = cand.filter(c => !seen.has(c.n) && seen.add(c.n)).slice(0, 2);
      const att = D.theirAtt(s), tf = muFront(mu.theirs, s), front = new Set(Object.values(tf));
      const calls = n => [...(sh.attackers.find(a => a.num === n)?.sits || []).filter(si => si.on && (si.block || '').trim()).map(si => `${SHEET.sitLabel(si)}: ${si.block.trim()}`),
        ...(sh.block || []).filter(b => b.num === n && (b.call || '').trim()).map(b => `${b.sit || ''}: ${b.call}`.trim())];
      const attack = Object.entries(att).sort((a, b) => b[1].sh - a[1].sh).slice(0, 3).map(([n, a]) => ({ n, name: nmT(n), role: roleT(n), share: Math.round(100 * a.sh), eff: a.eff, cnt: a.n, front: front.has(n), calls: calls(n) }));
      rot[s] = { cp: D.theirSo(s) != null ? Math.round(D.theirSo(s)) : null, front: ['4', '3', '2'].map(z => tf[z]).filter(Boolean).map(nmT), receivers: rv && Object.fromEntries(Object.entries(rv).map(([n, z]) => [z, nmT(n)])), serve, attack, note: sh.rot?.[s]?.note || '' };
    }
    return { app: 'foglio-gara-piano', v: 1, made: new Date().toISOString(), opp: sh.meta.opp || '', date: sh.meta.date || '', code: sh.meta.code || '',
      theirs: mu.theirs.map((n, i) => ({ n, name: nmT(n), role: MU_ROLE[i] })), theirL: mu.theirL ? { n: mu.theirL, name: nmT(mu.theirL) } : null,
      theySrv: mu.theySrv, theyRec: mu.theyRec, ours: { ord: mu.ours, lib: mu.ourL, srvStart: x.srvStart, recStart: x.recStart }, rot };
  }
  // the plan of each sheet stays in this browser too: the bench scout on the same device reads it without files
  let planTimer = null;
  function publishPlan(sh) {
    clearTimeout(planTimer);
    planTimer = setTimeout(() => {
      try {
        const plan = muPlan(sh); if (!plan) return;
        plan.sheet = sh.id;
        const all = JSON.parse(localStorage.getItem('fogliogara.plans') || '{}');
        all[sh.id] = plan;
        const keep = Object.entries(all).sort((a, b) => String(b[1].made).localeCompare(String(a[1].made))).slice(0, 12); // the 12 most recent
        localStorage.setItem('fogliogara.plans', JSON.stringify(Object.fromEntries(keep)));
      } catch { }
    }, 600);
  }
  function muExport() {
    const sh = state.sheet, plan = muPlan(sh);
    if (!plan) { toast('Piano non disponibile: servono scout dell’avversario e Campionato'); return; }
    const name = `Piano ${plan.opp} ${plan.date}.json`.replace(/[\\/:*?"<>|]/g, '');
    const blob = new Blob([JSON.stringify(plan)], { type: 'application/json' });
    if (state.downloads) state.downloads.save({ filename: name, data: blob }).catch(() => toast('Salvataggio annullato'));
    else { const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = name; document.body.appendChild(a); a.click(); setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 2000); }
  }

  /* ---------- video links: paste them all at once, matched by file name ---------- */
  function linkTarget(u) {
    let name = '';
    try { const url = new URL(u); name = url.searchParams.get('preview') || decodeURIComponent(url.pathname.split('/').pop() || ''); } catch { return null; }
    const base = name.split('/').pop().replace(/\.[a-z0-9]{2,4}$/i, '').trim(); // a file in a sub-folder: its own name
    // "A01 X5" = attack of 1 on combination X5 (one video per ball); "A01" = whole attacker; "B7" = serve of 7
    if (/muro/i.test(base)) return { kind: 'block', name }; // e.g. "A02 Muro": their block, link in Altre note
    if (/mont|complet|tutto|full/i.test(base)) return { kind: 'montage', name }; // before the numbers: "A02 Montaggio" is not attacker 2
    const mc = base.match(/^\s*a\s*0*(\d{1,2})(?!\d)\s*[-_ ]?\s*([a-z][a-z0-9])(?![a-z0-9])/i);
    if (mc) return { kind: 'att', num: String(parseInt(mc[1], 10)), combo: mc[2].toUpperCase(), name };
    const m = base.match(/^\s*([ab])\s*[-_ ]?\s*0*(\d{1,2})(?!\d)/i) || base.match(/(?:^|[^a-z])(att(?:acco)?|batt(?:uta)?)\s*[-_ ]?\s*0*(\d{1,2})(?!\d)/i);
    if (m) return { kind: /^a/i.test(m[1]) ? 'att' : 'srv', num: String(parseInt(m[2], 10)), name };
    if (/pall|alzat|setter/i.test(base)) return { kind: 'setter', name };
    if (/mont|complet|tutto|full/i.test(base)) return { kind: 'montage', name };
    return { kind: null, name };
  }
  // links into these shared folders are rebuilt from scratch at each «Collega»: old ones (moved or renamed files) go
  function clearFolderLinks(bases) {
    const sh = state.sheet, keys = bases.filter(Boolean).map(b => b.origin + b.pathname);
    const inF = u => { try { const x = new URL(u); return keys.includes(x.origin + x.pathname); } catch { return false; } };
    const clr = (o, k) => { if (o && o[k] && inF(o[k])) o[k] = ''; };
    clr(sh, 'blockVideo'); clr(sh, 'setterVideo'); clr(sh.meta, 'montage');
    for (const a of sh.attackers || []) { clr(a, 'video'); for (const x of a.sits || []) clr(x, 'video'); }
    for (const v of sh.servers || []) clr(v, 'video');
  }
  function assignLinks(text) {
    const sh = state.sheet;
    const urls = text.match(/https?:\/\/[^\s<>"']+/g) || [];
    if (!urls.length) { toast('Nessun link trovato nel testo incollato'); return; }
    let ok = 0; const miss = [];
    for (const u of urls) {
      const t = linkTarget(u);
      if (!t || !t.kind) { miss.push(t?.name || u); continue; }
      if (t.kind === 'setter') { sh.setterVideo = u; ok++; }
      else if (t.kind === 'montage') { sh.meta.montage = u; ok++; }
      else if (t.kind === 'block') { sh.blockVideo = u; ok++; }
      else if (t.kind === 'att') {
        let a = sh.attackers.find(x => x.num === t.num);
        if (!a) { a = { num: t.num, on: false, note: '', video: '', sits: [] }; sh.attackers.push(a); }
        if (t.combo) {
          const key = DVW.comboKey(t.combo, sh.stats?.combos, SHEET.player(sh, t.num).roleCode);
          let sit = key && a.sits.find(s => s.keys.includes(key));
          if (!sit && key) { sit = { keys: [key], on: false, block: '', note: '', manual: {} }; a.sits.push(sit); }
          if (sit) { sit.video = u; ok++; } else miss.push(t.name);
        } else { a.video = u; ok++; }
      } else {
        let s = sh.servers.find(x => x.num === t.num);
        if (!s) { s = { num: t.num, on: false, note: '', video: '', targets: [] }; sh.servers.push(s); }
        s.video = u; ok++;
      }
    }
    touch(); renderEditor();
    toast(`${ok} link assegnati${miss.length ? `, ${miss.length} non riconosciuti` : ''}`);
    if (miss.length) $('#v_miss').textContent = 'Non riconosciuti: ' + miss.join(', ');
  }
  /* ---------- video from a shared Dropbox folder: one public, view-only folder link per match ---------- */
  const VIDEO_EXT = /\.(mp4|mov|m4v|avi|mkv|webm)$/i;
  function folderBase(raw) {
    try {
      const u = new URL(String(raw || '').trim());
      if (!/dropbox\.com$/i.test(u.hostname) || !/^\/scl\/fo\//.test(u.pathname)) return null;
      u.searchParams.delete('st'); u.searchParams.delete('preview');
      return u;
    } catch { return null; }
  }
  // link of one file inside the shared folder: Dropbox opens that video directly
  function fileLink(base, name) { const u = new URL(base.toString()); u.searchParams.set('preview', name); u.searchParams.set('dl', '0'); return u.toString(); }
  function linkNames(names) {
    const sh = state.sheet; const base = folderLinks(sh.videoFolder).find(f => f.base)?.base;
    if (!base) { setVStatus('Incolla prima il link della cartella (Dropbox, «Copia link»).', true); return; }
    const vids = names.map(n => n.split('/').slice(1).join('/') || n).filter(n => VIDEO_EXT.test(n)); // "A03 Novi/Montaggi/Muro.mp4" -> "Montaggi/Muro.mp4"
    if (!vids.length) { setVStatus('Nella cartella non ci sono video.', true); return; }
    assignLinks(vids.map(n => fileLink(base, n)).join('\n'));
    setVStatus(`${vids.length} video trovati nella cartella.`);
  }
  // one or more folder links, one per line (e.g. the sub-folders Video, Attaccanti, Battute of the match)
  const e2path = e => e.path_display || e.path; // a sub-folder entry, as list_folder gives it back
  function folderLinks(raw) { return String(raw || '').split(/[\s,]+/).map(x => x.trim()).filter(x => /^https?:\/\//i.test(x)).map(x => ({ raw: x, base: folderBase(x) })); }
  function setVStatus(t, warn) { const el = $('#v_fstatus'); if (el) { el.textContent = t; el.classList.toggle('warnTxt', !!warn); } }
  async function linkFolder() {
    const sh = state.sheet;
    const fl = folderLinks(sh.videoFolder);
    if (!fl.length || fl.some(f => !f.base)) { setVStatus('Ogni link deve essere quello di una cartella Dropbox (www.dropbox.com/scl/fo/…), uno per riga.', true); return; }
    const pick = () => { setVStatus('Scegli dal computer la cartella della partita (la stessa che hai condiviso): leggo solo i nomi dei file, non li carico.'); $('#v_files')?.click(); };
    const mcp = await (window.claude?.use ? window.claude.use('mcp') : Promise.resolve(null)).catch(() => null);
    if (!mcp) { pick(); return; }
    setVStatus('Leggo la cartella su Dropbox…');
    try {
      // each folder link gives the links of the videos directly inside that folder (not of its sub-folders)
      const urls = [], warn = [], per = [];
      for (const f of fl) {
        const meta = (await mcp.callTool('Dropbox', 'get_shared_link_metadata', { url: f.raw })).payload?.link || {};
        const fname = meta.name || meta.path_lower?.split('/').pop() || 'cartella';
        if (meta.audience && meta.audience !== 'public') warn.push(`${fname}: il link non è pubblico, i giocatori non vedrebbero i video`);
        if (meta.access_level === 'edit') warn.push(`${fname}: il link permette di modificare la cartella, in Dropbox mettilo su «Può visualizzare»`);
        if (!meta.path_lower) { warn.push(`non trovo nel tuo Dropbox la cartella di un link`); continue; }
        // with a single link the sub-folders (one level) are read too: a file there gets "preview=<sub-folder>/<name>",
        // which Dropbox opens as that video (checked on a phone without the Dropbox app)
        const deep = fl.length === 1;
        const listAll = async path => {
          const out = [];
          let res = (await mcp.callTool('Dropbox', 'list_folder', { path, recursive: false })).payload || {};
          for (let guard = 0; ; guard++) {
            out.push(...(res.entries || []));
            if (!res.has_more || !res.cursor || guard > 20) break;
            res = (await mcp.callTool('Dropbox', 'list_folder', { cursor: res.cursor })).payload || {};
          }
          return out;
        };
        let n = 0;
        // walk the folder and its sub-folders (up to 3 levels): a file there gets "preview=<sub>/<sub>/<name>"
        const walk = async (path, rel, level) => {
          for (const e of await listAll(path)) {
            if (!e.name) continue;
            if (e.object_type === 'folder') { if (deep && level < 3) await walk(e2path(e), rel + e.name + '/', level + 1); continue; }
            if (VIDEO_EXT.test(e.name)) { urls.push(fileLink(f.base, rel + e.name)); n++; }
          }
        };
        await walk(meta.path_lower, '', 0);
        per.push(`${fname}: ${n}`);
      }
      if (!urls.length) { setVStatus(`Nelle cartelle non ci sono video${warn.length ? ' · ' + warn.join('; ') : ''}.`, true); return; }
      clearFolderLinks(fl.map(f => f.base));
      assignLinks(urls.join('\n'));
      setVStatus(`${urls.length} video trovati (${per.join(' · ')}).${warn.length ? ' Attenzione: ' + warn.join('; ') + '.' : ''}`, !!warn.length);
    } catch (e) {
      const c = e?.code;
      if (c === 'server_not_connected' || c === 'needs_reauth') { setVStatus('Dropbox non è collegato: collegalo in claude.ai → Impostazioni → Connettori, oppure scegli i video dal computer.', true); pick(); }
      else if (c === 'not_in_manifest' || c === 'approval_required' || c === 'consent_required') setVStatus('Serve il tuo permesso per leggere la cartella su Dropbox: riprova e consenti, oppure scegli i video dal computer.', true);
      else if (c === 'tool_error') setVStatus('Dropbox non ha trovato il link o la cartella: controlla il link.', true);
      else { setVStatus('Dropbox non risponde ora: scegli i video dal computer, oppure riprova tra poco.', true); pick(); }
    }
  }
  function renderVideo() {
    const sh = state.sheet; const el = $('#secVideo');
    const srv = sh.servers.filter(s => s.on), att = sh.attackers.filter(a => a.on);
    const row = (label, url, req) => `<li class="${url ? 'ok' : req ? 'miss' : ''}"><span>${esc(label)}</span><small>${url ? 'collegato' : req ? 'manca' : '—'}</small></li>`;
    el.innerHTML = `
      <div class="vfolder">
        <label class="fld" for="v_folder"><span>Cartella video della partita (Dropbox → Condividi → «Chiunque abbia il link», «Può visualizzare» → Copia link). Basta il link della cartella della partita: legge anche le sottocartelle, fino a tre livelli (es. Montaggi → Attaccanti). Dopo aver spostato o rinominato file, premi di nuovo il tasto.</span><textarea id="v_folder" rows="3" placeholder="https://www.dropbox.com/scl/fo/…  (Video)&#10;https://www.dropbox.com/scl/fo/…  (Attaccanti)&#10;https://www.dropbox.com/scl/fo/…  (Battute)">${esc(sh.videoFolder || '')}</textarea></label>
        <button class="btn small" id="v_folder_go" type="button">Collega i video delle cartelle</button>
        <input id="v_files" type="file" webkitdirectory multiple hidden>
        <small class="hint" id="v_fstatus"></small>
      </div>
      <p class="hint">Nomi dei file: <b>A</b> + numero + combinazione per ogni palla d’attacco (<code>A01 X5.mp4</code> spinta in 4, <code>A01 V5.mp4</code> alta in 4), <b>A</b> + numero per un video unico dell’attaccante, <b>B</b> + numero per la battuta (<code>B7.mp4</code>), oppure <b>palleggio</b> e <b>montaggio</b>. Poi incolla qui tutti i link Dropbox insieme.</p>
      <label class="fld" for="v_paste"><span>Link da assegnare</span><textarea id="v_paste" rows="4" placeholder="https://www.dropbox.com/scl/fi/…/A33.mp4?rlkey=…"></textarea></label>
      <button class="btn small" id="v_assign" type="button">Assegna i link</button>
      <small class="hint" id="v_miss"></small>
      <div class="extraLinks"><small class="hint">Link aggiuntivi (compaiono in alto nella pagina 1)</small>
        ${[0, 1, 2, 3].map(i => { const l = (sh.links || [])[i] || {}; return `<div class="linkRow"><input id="l_lab_${i}" value="${esc(l.label || '')}" placeholder="Etichetta"><input id="l_url_${i}" type="url" value="${esc(l.url || '')}" placeholder="https://…"></div>`; }).join('')}
      </div>
      <ul class="vlist">
        ${row('Montaggio completo', sh.meta.montage)}${row('Palleggio', sh.setterVideo)}${row('Muro avversario (Altre note)', sh.blockVideo)}
        ${att.map(a => row('Attacco · ' + nm(sh, a.num) + ' (unico)', a.video) + a.sits.filter(s => s.on).map(s => row('   ' + SHEET.sitLabel(s, true), s.video)).join('')).join('')}
        ${srv.map(s => row('Battuta · ' + nm(sh, s.num), s.video, true)).join('')}
      </ul>`;
  }
  function useInsight(id, where) {
    const sh = state.sheet;
    const x = insights(sh).find(i => i.id === id); if (!x) return;
    if (where === 'key') {
      const i = sh.keys.findIndex(k => !(k || '').trim());
      if (i < 0) { toast('Le 3 chiavi sono già piene'); return; }
      sh.keys[i] = x.key; toast('Aggiunta alle chiavi');
    } else if (x.cat === 'Palleggio') { sh.setterNotes = [sh.setterNotes, x.text].filter(Boolean).join('\n'); toast('Aggiunta alle note sul palleggio'); }
    else { sh.notes = [sh.notes, x.text].filter(Boolean).join('\n'); toast('Aggiunta alle note del muro'); }
    touch(); renderEditor();
  }
  // "A02" = second round of the first leg, "R05" = fifth of the return leg
  function roundCode(r) {
    const half = Math.max(...CAL.games.map(g => +g[0] || 0)) / 2;
    if (!(r > 0) || !(half > 0)) return '';
    const leg = r <= half ? 'A' : 'R', n = r <= half ? r : r - half;
    return leg + String(n).padStart(2, '0');
  }
  function pickGame(i) {
    const g = CAL.games[+i]; if (!g) return;
    const sh = state.sheet, t = CAL.teams[g[4]] || { short: g[4] };
    sh.meta.opp = t.short; sh.meta.oppFull = g[4]; sh.meta.date = g[1];
    sh.meta.match = `${g[0]}ª giornata · ${g[3] ? 'in casa' : 'in trasferta'} · ore ${g[2]}`;
    sh.meta.code = roundCode(g[0]);
    sh.meta.venue = g[5];
    if (t.logo && LOGOS[t.logo]) sh.meta.logo = LOGOS[t.logo];
    touch(); renderEditor(); renderSheetSelect();
  }


